<?php
/* Zohal Card Inquiry — تک‌فایلی؛ قرارداد API را با مستندات حساب خود تطبیق دهید. */
declare(strict_types=1);
// پیکربندی از محیط سرور؛ جایگزین ثابت‌ها فقط در صورت تنظیم آگاهانه در همین فایل.
const ZOHAL_URL_FALLBACK = '';
const ZOHAL_TOKEN_FALLBACK = '';
function envv(string $k,string $d=''): string { $v=getenv($k); return $v===false?$d:trim((string)$v); }
$cfg=[
 'url'=>envv('ZOHAL_API_URL',ZOHAL_URL_FALLBACK), 'token'=>envv('ZOHAL_API_TOKEN',ZOHAL_TOKEN_FALLBACK),
 'header'=>envv('ZOHAL_AUTH_HEADER','Authorization'), 'scheme'=>envv('ZOHAL_AUTH_SCHEME','Bearer'),
 'method'=>strtoupper(envv('ZOHAL_HTTP_METHOD','POST')), 'field'=>envv('ZOHAL_CARD_FIELD','card_number'),
 'timeout'=>(int)envv('ZOHAL_TIMEOUT','15'), 'tls'=>filter_var(envv('ZOHAL_VERIFY_TLS','true'),FILTER_VALIDATE_BOOLEAN),
 'demo'=>filter_var(envv('ZOHAL_DEMO','false'),FILTER_VALIDATE_BOOLEAN)
];
$https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||((int)($_SERVER['SERVER_PORT']??0)===443);
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$https,'httponly'=>true,'samesite'=>'Strict']);
ini_set('session.use_strict_mode','1'); session_start();
if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32));
function jsonout(array $x,int $status=200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function configured(array $c): bool { return filter_var($c['url'],FILTER_VALIDATE_URL)!==false && str_starts_with(strtolower($c['url']),'https://') && $c['token']!=='' && preg_match('/^[A-Za-z0-9_-]+$/',$c['header']) && preg_match('/^[A-Za-z0-9._-]*$/',$c['scheme']) && preg_match('/^[A-Za-z0-9_-]+$/',$c['field']) && in_array($c['method'],['POST','GET'],true) && $c['timeout']>=2 && $c['timeout']<=60; }
function digits(string $s): string { return strtr($s,['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']); }
function cleanpan($v): string { return preg_replace('/[\s\-‐‑–—]+/u','',digits((string)$v))??''; }
function luhn(string $n): bool { $sum=0;$dbl=false; for($i=strlen($n)-1;$i>=0;$i--){$d=(int)$n[$i];if($dbl){$d*=2;if($d>9)$d-=9;}$sum+=$d;$dbl=!$dbl;} return $sum%10===0; }
function bank(string $n): string { $bin=substr($n,0,6); $m=['603799'=>'بانک ملی','589210'=>'بانک سپه','627648'=>'بانک توسعه صادرات','627961'=>'بانک صنعت و معدن','603770'=>'بانک کشاورزی','628023'=>'بانک مسکن','627760'=>'پست بانک','502908'=>'بانک توسعه تعاون','627412'=>'بانک اقتصاد نوین','622106'=>'بانک پارسیان','502229'=>'بانک پاسارگاد','639347'=>'بانک پاسارگاد','621986'=>'بانک سامان','639346'=>'بانک سینا','639607'=>'بانک سرمایه','636214'=>'بانک آینده','505416'=>'بانک گردشگری','505785'=>'بانک ایران‌زمین','589463'=>'بانک رفاه','627381'=>'بانک انصار','639599'=>'بانک قوامین','627488'=>'بانک کارآفرین','502910'=>'بانک کارآفرین','627488'=>'بانک کارآفرین','627353'=>'بانک تجارت','585983'=>'بانک تجارت','589463'=>'بانک رفاه','610433'=>'بانک ملت','991975'=>'بانک ملت','627353'=>'بانک تجارت','627414'=>'بانک ملی','627884'=>'بانک پارسیان','627567'=>'بانک صادرات','603769'=>'بانک صادرات','627341'=>'بانک صادرات','606256'=>'مؤسسه اعتباری ملل','636949'=>'بانک حکمت ایرانیان','505801'=>'مؤسسه کوثر','507677'=>'مؤسسه نور']; return $m[$bin]??'بانک نامشخص'; }
function cardcheck(string $raw): array { $p=cleanpan($raw); if(!preg_match('/^\d{16}$/',$p))return [false,'شماره کارت باید ۱۶ رقم باشد.','']; if(!luhn($p))return [false,'رقم کنترلی کارت معتبر نیست.','']; return [true,'',$p]; }
function maskcard(string $p): string { return substr($p,0,4).' **** **** '.substr($p,-4); }
function findname($v,int $depth=0): string { if($depth>5||!is_array($v))return ''; foreach(['name','full_name','card_holder_name','holder_name','owner_name'] as $k)if(isset($v[$k])&&is_string($v[$k])&&trim($v[$k])!=='')return mb_substr(trim($v[$k]),0,120); foreach(['data','result','response'] as $k)if(isset($v[$k])){$n=findname($v[$k],$depth+1);if($n!=='')return $n;} return ''; }
function inquiry(string $pan,array $c): array {
 $demo=$c['demo']; if(!$demo&&!configured($c))return ['ok'=>false,'message'=>'سرویس تولید تنظیم نشده است؛ راهنمای تنظیمات را ببینید.'];
 if($demo){return ['ok'=>true,'message'=>'نتیجهٔ نمایشی؛ اطلاعات واقعی نیست.','name'=>'نمونهٔ نمایشی — غیرواقعی','source'=>'demo'];}
 if(!function_exists('curl_init'))return ['ok'=>false,'message'=>'افزونهٔ cURL روی سرور فعال نیست.'];
 $body=json_encode([$c['field']=>$pan],JSON_UNESCAPED_UNICODE); $url=$c['url']; if($c['method']==='GET')$url.=(str_contains($url,'?')?'&':'?').http_build_query([$c['field']=>$pan]);
 $headers=['Accept: application/json','Content-Type: application/json']; $auth=trim($c['scheme'].' '.$c['token']); $headers[]=$c['header'].': '.$auth;
 $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>min(8,$c['timeout']),CURLOPT_TIMEOUT=>$c['timeout'],CURLOPT_SSL_VERIFYPEER=>$c['tls'],CURLOPT_SSL_VERIFYHOST=>$c['tls']?2:0,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_MAXREDIRS=>0]);
 if($c['method']==='POST'){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,$body);} $raw=curl_exec($ch);$err=curl_errno($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
 if($raw===false||$err){return ['ok'=>false,'message'=>$err===CURLE_OPERATION_TIMEDOUT?'مهلت اتصال به سرویس پایان یافت.':'خطای ارتباط با سرویس؛ بعداً تلاش کنید.'];}
 if($http===429)return ['ok'=>false,'message'=>'محدودیت درخواست سرویس فعال است؛ کمی بعد تلاش کنید.']; if($http<200||$http>=300)return ['ok'=>false,'message'=>'سرویس درخواست را نپذیرفت (HTTP '.$http.').'];
 $data=json_decode((string)$raw,true); unset($raw); if(!is_array($data))return ['ok'=>false,'message'=>'پاسخ سرویس JSON معتبر نبود.']; $name=findname($data); if($name==='')return ['ok'=>false,'message'=>'نام دارنده در پاسخ سرویس یافت نشد.']; return ['ok'=>true,'message'=>'استعلام با موفقیت انجام شد.','name'=>$name,'source'=>'production'];
}
function rateok(): bool { $now=time();$ip=hash('sha256',(string)($_SERVER['REMOTE_ADDR']??'unknown')); $key='rl_'.$ip; $a=array_values(array_filter($_SESSION[$key]??[],fn($t)=>$t>$now-60)); if(count($a)>=20){$_SESSION[$key]=$a;return false;} $a[]=$now;$_SESSION[$key]=$a;return true; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 $in=json_decode(file_get_contents('php://input')?:'',true); if(!is_array($in))$in=$_POST;
 if(!hash_equals((string)$_SESSION['csrf'],(string)($in['csrf']??'')))jsonout(['ok'=>false,'message'=>'نشست معتبر نیست؛ صفحه را تازه کنید.'],403);
 $action=(string)($in['action']??''); if($action==='health')jsonout(['ok'=>true,'configured'=>$cfg['demo']||configured($cfg),'demo'=>$cfg['demo'],'message'=>$cfg['demo']?'حالت نمایشی روشن است؛ نتایج واقعی نیستند.':(configured($cfg)?'پیکربندی سرور موجود است.':'API تنظیم نشده است.')]);
 if(!in_array($action,['inquiry','batch'],true))jsonout(['ok'=>false,'message'=>'درخواست نامعتبر است.'],400); if(!rateok())jsonout(['ok'=>false,'message'=>'تعداد درخواست‌ها زیاد است؛ یک دقیقه دیگر تلاش کنید.'],429);
 if($action==='inquiry'){$v=cardcheck($in['card']??'');if(!$v[0])jsonout(['ok'=>false,'message'=>$v[1]],422);$r=inquiry($v[2],$cfg);$out=['ok'=>$r['ok'],'message'=>$r['message'],'result'=>['card'=>maskcard($v[2]),'last4'=>substr($v[2],-4),'bank'=>bank($v[2]),'name'=>$r['name']??'','source'=>$r['source']??($cfg['demo']?'demo':'production'),'time'=>date(DATE_ATOM)]];jsonout($out,$r['ok']?200:502);}
 $rawcards=$in['cards']??''; if(!is_string($rawcards))jsonout(['ok'=>false,'message'=>'ورودی دسته‌ای نامعتبر است.'],422);$items=preg_split('/[\r\n,;]+/u',$rawcards,-1,PREG_SPLIT_NO_EMPTY)?:[]; $items=array_values(array_filter(array_map('trim',$items),fn($x)=>$x!=='')); if(count($items)>50)jsonout(['ok'=>false,'message'=>'حداکثر ۵۰ کارت در هر دسته پذیرفته می‌شود.'],422); if(!$items)jsonout(['ok'=>false,'message'=>'شماره‌ای برای بررسی وارد نشده است.'],422);
 $results=[];foreach($items as $item){$v=cardcheck($item);if(!$v[0]){$results[]=['ok'=>false,'message'=>$v[1],'card'=>'نامعتبر','last4'=>'','bank'=>'—','name'=>'','source'=>$cfg['demo']?'demo':'production','time'=>date(DATE_ATOM)];continue;} $r=inquiry($v[2],$cfg);$results[]=['ok'=>$r['ok'],'message'=>$r['message'],'card'=>maskcard($v[2]),'last4'=>substr($v[2],-4),'bank'=>bank($v[2]),'name'=>$r['name']??'','source'=>$r['source']??($cfg['demo']?'demo':'production'),'time'=>date(DATE_ATOM)];} jsonout(['ok'=>true,'message'=>'پردازش دسته‌ای انجام شد.','results'=>$results]);
}
header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header('Cache-Control: no-store');
$csrf=json_encode($_SESSION['csrf'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP);$isConfigured=$cfg['demo']||configured($cfg);$status=$cfg['demo']?'حالت نمایشی روشن است — نتایج واقعی نیستند':($isConfigured?'API پیکربندی شده':'API هنوز پیکربندی نشده');
?>
