row{display:flex;gap:7px}.input,textarea{width:100%;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);padding:11px 12px;outline:none}.input:focus,textarea:focus{border-color:var(--teal);box-shadow:0 0 0 3px color-mix(in srgb,var(--teal) 18%,transparent)}textarea{min-height:112px;resize:vertical}.smallbtn{padding:7px 10px;white-space:nowrap}.valid{font-size:12px;color:var(--muted);margin-top:4px}.valid.good{color:var(--teal)}.valid.bad{color:var(--red)}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.result{min-height:216px}.empty{display:grid;place-items:center;text-align:center;min-height:175px;color:var(--muted)}.resultbox{display:none}.resultbox.show{display:block}.result-name{font-size:23px;font-weight:bold;margin:14px 0}.kv{display:grid;grid-template-columns:1fr 1fr;gap:9px}.kv div{padding:9px;background:var(--bg);border-radius:9px}.kv small{display:block;color:var(--muted)}.tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin:20px 0 14px}.tab{border:0;background:transparent;color:var(--muted);padding:8px 12px;border-bottom:2px solid transparent}.tab.active{color:var(--teal);border-color:var(--teal);font-weight:bold}.pane{display:none}.pane.active{display:block}.batchpreview{padding:8px 10px;background:var(--bg);border-radius:8px;margin:8px 0;font-size:13px}.progress{height:7px;background:var(--line);border-radius:9px;overflow:hidden;margin:8px 0}.progress i{display:block;height:100%;width:0;background:var(--teal);transition:width .2s}.tablewrap{overflow:auto;max-height:320px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:right;border-bottom:1px solid var(--line);padding:8px;white-space:nowrap}th{color:var(--muted)}details{margin-top:14px;border-top:1px solid var(--line);padding-top:12px}summary{cursor:pointer;font-weight:bold}.historytools{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.historytools input{max-width:280px}.toast{position:fixed;bottom:20px;left:20px;max-width:90vw;background:var(--ink);color:var(--paper);padding:11px 16px;border-radius:10px;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);transition:.2s;pointer-events:none;z-index:5}.toast.on{opacity:1;transform:none}.spin{display:inline-block;width:15px;height:15px;border:2px solid #ffffff77;border-top-color:white;border-radius:50%;animation:s .7s linear infinite;vertical-align:-3px;margin-left:6px}@keyframes s{to{transform:rotate(360deg)}}footer{color:var(--muted);font-size:12px;text-align:center;padding:20px}@media(max-width:760px){.wrap{padding:14px}.grid{grid-template-columns:1fr}.top{align-items:flex-start}.brand h1{font-size:18px}.statusline{align-items:flex-start;flex-direction:column}.kv{grid-template-columns:1fr 1fr}}@media print{.top,.notice,.tabs,form,details,footer,.actions,.btn{display:none!important}.wrap{max-width:100%;padding:0}.card{box-shadow:none;border:0}.resultbox{display:block!important}}
</style></head><body><div class="wrap">
<header class="top"><div class="brand"><div class="mark" aria-hidden="true">◈</div><div><h1>استعلام نام دارنده کارت</h1><p>درگاه سازمانی زحل · استعلام مجاز و کنترل‌شده</p></div></div><div class="actions"><button class="btn" id="themeBtn" aria-label="تغییر پوسته">◐ پوسته</button></div></header>
<div class="notice"><div class="statusline"><span><b>نکتهٔ راه‌اندازی:</b> ارتباط واقعی فقط پس از تنظیم API در محیط سرور فعال است. قرارداد، مسیر و قالب پاسخ Zohal باید دقیقاً با مستندات حساب شما منطبق باشد؛ این برنامه قرارداد خصوصی سرویس را حدس نمی‌زند.</span><span class="pill"><?=htmlspecialchars($status,ENT_QUOTES,'UTF-8')?></span></div></div>
<section class="grid"><div class="card"><h2>استعلام تکی</h2><p class="muted">شماره کارت فقط برای پردازش همین درخواست استفاده می‌شود و در سرور ذخیره نمی‌شود.</p>
<form id="singleForm"><div class="field"><label for="cardInput">شمارهٔ ۱۶ رقمی کارت</label><div class="inputrow"><input id="cardInput" class="input" inputmode="numeric" autocomplete="off" maxlength="32" aria-describedby="cardState" placeholder="مثلاً ۶۰۳۷…" required><button class="btn smallbtn" type="button" id="pasteBtn">چسباندن</button><button class="btn smallbtn" type="button" id="revealBtn">نمایش</button></div><div class="row"><button class="btn smallbtn" type="button" id="clearBtn">پاک‌کردن</button><span id="cardState" class="valid" aria-live="polite">۱۶ رقم وارد کنید.</span></div></div><button class="btn primary" id="submitBtn" type="submit">استعلام نام</button></form></div>
<div class="card result" aria-live="polite"><h2>نتیجه</h2><div id="emptyResult" class="empty">پس از ارسال استعلام، نتیجهٔ محدود و ماسک‌شده اینجا نمایش داده می‌شود.</div><div id="resultBox" class="resultbox"><div class="row"><span id="sourcePill" class="pill"></span><span id="resultTime" class="muted"></span></div><div class="result-name" id="resultName">—</div><div class="kv"><div><small>شمارهٔ ماسک‌شده</small><b id="resultCard">—</b></div><div><small>بانک</small><b id="resultBank">—</b></div><div><small>وضعیت</small><b id="resultStatus">—</b></div><div><small>چهار رقم پایانی</small><b id="resultLast">—</b></div></div><div class="row" style="margin-top:12px"><button class="btn" id="copyName">کپی نام</button><button class="btn" id="printBtn">چاپ رسید</button></div></div></div></section>
<nav class="tabs" aria-label="بخش‌های برنامه"><button class="tab active" data-tab="batchPane">دسته‌ای</button><button class="tab" data-tab="historyPane">تاریخچهٔ محلی</button></nav>
<section id="batchPane" class="pane active card"><h2>پردازش دسته‌ای از ورودی کاربر</h2><p class="muted">فقط CSV/متن ارسالی شما؛ هر خط یک کارت یا ستون اول CSV. حداکثر ۵۰ مورد، پردازش ترتیبی و بدون تأخیر ساختگی.</p><div class="field"><label for="batchText">شماره‌ها (خط، ویرگول یا نقطه‌ویرگول)</label><textarea id="batchText" placeholder="شمارهٔ کارت در هر خط"></textarea></div><div class="row"><label class="btn smallbtn" for="csvFile">انتخاب فایل CSV</label><input id="csvFile" type="file" accept=".csv,text/csv" hidden><span id="fileName" class="muted"></span><button class="btn primary" id="batchBtn">اجرای دسته</button></div><div id="batchPreview" class="batchpreview">۰ مورد شناسایی شد.</div><div class="progress" aria-label="پیشرفت"><i id="progressBar"></i></div><div class="row"><button class="btn" id="batchCsv" disabled>خروجی CSV ماسک‌شده</button><button class="btn" id="batchJson" disabled>خروجی JSON ماسک‌شده</button></div><div class="tablewrap"><table><thead><tr><th>کارت ماسک‌شده</th><th>بانک</th><th>نام</th><th>وضعیت</th><th>منبع</th></tr></thead><tbody id="batchRows"></tbody></table></div></section>
<section id="historyPane" class="pane card"><h2>تاریخچهٔ همین مرورگر</h2><p class="muted">در localStorage فقط کارت ماسک‌شده و دادهٔ نتیجه نگهداری می‌شود؛ هیچ شمارهٔ کامل کارت ذخیره نمی‌شود.</p><div class="historytools"><input class="input" id="historySearch" placeholder="جست‌وجو در نام، بانک یا چهار رقم پایانی"><button class="btn" id="historyCsv">خروجی CSV</button><button class="btn" id="historyJson">خروجی JSON</button><button class="btn" id="clearHistory">پاک‌کردن همه</button></div><div id="stats" class="muted"></div><div class="tablewrap"><table><thead><tr><th>زمان</th><th>کارت</th><th>بانک</th><th>نام</th><th>منبع</th><th></th></tr></thead><tbody id="historyRows"></tbody></table></div></section>
<details class="card"><summary>راهنمای پیکربندی سرور</summary><p>تنظیم متغیرهای محیطی PHP-FPM/وب‌سرور (نه مرورگر):</p><ul><li><code>ZOHAL_API_URL</code> و <code>ZOHAL_API_TOKEN</code> (توکن هرگز به HTML/JS فرستاده نمی‌شود)</li><li><code>ZOHAL_AUTH_HEADER</code> پیش‌فرض Authorization؛ <code>ZOHAL_AUTH_SCHEME</code> پیش‌فرض Bearer</li><li><code>ZOHAL_HTTP_METHOD</code> پیش‌فرض POST (POST بدنهٔ JSON می‌فرستد؛ GET پارامتر URL)</li><li><code>ZOHAL_CARD_FIELD</code> پیش‌فرض card_number؛ <code>ZOHAL_TIMEOUT</code> پیش‌فرض ۱۵ ثانیه</li><li><code>ZOHAL_VERIFY_TLS</code> پیش‌فرض true؛ <code>ZOHAL_DEMO</code> پیش‌فرض false</li></ul><p>در حالت تولید URL باید HTTPS باشد. API باید فیلد قابل‌تنظیم کارت را بپذیرد و پاسخ JSON دارای یکی از کلیدهای نام شناخته‌شده باشد. پیام و بدنهٔ خام سرویس افشا/ذخیره نمی‌شود. حالت نمایشی فقط با <code>ZOHAL_DEMO=true</code> روی سرور روشن می‌شود و نام نمونهٔ آن به‌وضوح غیرواقعی است؛ مرورگر نمی‌تواند حالت تولید را به دمو یا برعکس تحمیل کند.</p></details>
<footer>برای استعلام مجاز و با رضایت دارنده استفاده کنید. از ارسال فهرست‌های غیرمجاز خودداری شود.</footer></div><div id="toast" class="toast" role="status" aria-live="polite"></div>
<script>
(()=>{'use strict';const csrf=<?=$csrf?>,demo=<?= $cfg['demo']?'true':'false' ?>,storage='zohal_inquiry_history_v1';let batchResults=[];const $=id=>document.getElementById(id),toast=m=>{const t=$('toast');t.textContent=m;t.classList.add('on');setTimeout(()=>t.classList.remove('on'),2800)},faNum=s=>String(s).replace(/[۰-۹٠-٩]/g,c=>'۰۱۲۳۴۵۶۷۸۹'[('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩'.indexOf(c)%10)]),digits=s=>String(s).replace(/[۰-۹٠-٩]/g,c=>String(('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩'.indexOf(c)%10))),norm=s=>digits(s).replace(/[\s\-‐‑–—]+/g,''),mask=p=>p.length===16?p.slice(0,4)+' **** **** '+p.slice(-4):'نامعتبر';
function valid(p){if(!/^\d{16}$/.test(p))return false;let s=0,d=false;for(let i=15;i>=0;i--){let n=+p[i];if(d){n*=2;if(n>9)n-=9}s+=n;d=!d}return s%10===0}
function bank(p){let m={'603799':'بانک ملی','589210':'بانک سپه','627648':'بانک توسعه صادرات','627961':'بانک صنعت و معدن','603770':'بانک کشاورزی','628023':'بانک مسکن','627760':'پست بانک','502908':'بانک توسعه تعاون','627412':'بانک اقتصاد نوین','622106':'بانک پارسیان','502229':'بانک پاسارگاد','639347':'بانک پاسارگاد','621986':'بانک سامان','639346':'بانک سینا','639607':'بانک سرمایه','636214':'بانک آینده','505416':'بانک گردشگری','505785':'بانک ایران‌زمین','589463':'بانک رفاه','627381':'بانک انصار','639599':'بانک قوامین','627353':'بانک تجارت','585983':'بانک تجارت','610433':'بانک ملت','991975':'بانک ملت','627567':'بانک صادرات','603769':'بانک صادرات','606256':'مؤسسه اعتباری ملل','636949':'بانک حکمت ایرانیان','505801':'مؤسسه کوثر','507677':'مؤسسه نور'};return m[p.slice(0,6)]||'بانک نامشخص'}
function history(){try{let a=JSON.parse(localStorage.getItem(storage)||'[]');return Array.isArray(a)?a:[]}catch(_){return []}}function saveHistory(a){try{localStorage.setItem(storage,JSON.stringify(a.slice(0,100)))}catch(_){toast('فضای ذخیره‌سازی مرورگر در دسترس نیست.')}}function addHistory(r){let a=history();a.unshift({...r,id:Date.now()+'-'+Math.random().toString(36).slice(2)});saveHistory(a);renderHistory()}
function sourceText(s){return s==='demo'?'نمایشی — غیرواقعی':'تولید'}function showResult(r){$('emptyResult').style.display='none';$('resultBox').classList.add('show');$('resultCard').textContent=r.card||'—';$('resultBank').textContent=r.bank||'—';$('resultName').textContent=r.name||'نام در دسترس نیست';$('resultLast').textContent=r.last4||'—';$('resultStatus').textContent=r.ok?'موفق':'ناموفق';$('sourcePill').textContent=sourceText(r.source);$('resultTime').textContent=new Date(r.time||Date.now()).toLocaleString('fa-IR');$('copyName').disabled=!r.name;}
async function post(action,data){const res=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({action,csrf,...data})});let j;try{j=await res.json()}catch(_){throw Error('پاسخ سرور قابل‌خواندن نیست.')}if(!res.ok&&!j)return Promise.reject(Error('خطای ارتباطی سرور.'));return j}
function setbusy(btn,on,label){btn.disabled=on;btn.innerHTML=on?'<span class="spin" aria-hidden="true"></span>در حال پردازش…':label}
const input=$('cardInput'),state=$('cardState');function checkInput(){let p=norm(input.value);input.value=input.value.replace(/[^۰-۹٠-٩0-9\s\-‐‑–—]/g,'');if(!p){state.textContent='۱۶ رقم وارد کنید.';state.className='valid';return}if(p.length===16&&valid(p)){state.textContent='ساختار و رقم کنترلی معتبر · '+bank(p);state.className='valid good'}else{state.textContent=p.length===16?'رقم کنترلی نامعتبر است.':`${faNum(p.length)} رقم از ۱۶ رقم`;state.className='valid '+(p.length===16?'bad':'')}}input.addEventListener('input',checkInput);
$('pasteBtn').onclick=async()=>{try{input.value=await navigator.clipboard.readText();checkInput();input.focus()}catch(_){toast('دسترسی چسباندن ممکن نیست؛ دستی وارد کنید.')}};$('clearBtn').onclick=()=>{input.value='';checkInput();input.focus()};$('revealBtn').onclick=()=>{const show=input.type==='password';input.type=show?'text':'password';$('revealBtn').textContent=show?'پنهان‌کردن':'نمایش'};input.type='password';
$('singleForm').addEventListener('submit',async e=>{e.preventDefault();let p=norm(input.value);if(!valid(p)){toast('شمارهٔ کارت معتبر وارد کنید.');return}const b=$('submitBtn');setbusy(b,true,'استعلام نام');try{let j=await post('inquiry',{card:p});if(j.result){showResult(j.result);addHistory(j.result)}toast(j.message||'درخواست انجام شد.')}catch(err){toast(err.message)}finally{setbusy(b,false,'استعلام نام')}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')$('singleForm').requestSubmit()});$('copyName').onclick=async()=>{try{await navigator.clipboard.writeText($('resultName').textContent);toast('نام کپی شد.')}catch(_){toast('کپی در دسترس نیست.')}};$('printBtn').onclick=()=>print();
$('themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('zohal_theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('zohal_theme')==='dark')document.body.classList.add('dark');
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.pane').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active');if(b.dataset.tab==='historyPane')renderHistory()});
const ta=$('batchText');function parseBatch(){return ta.value.split(/[\r\n,;]+/).map(x=>x.trim()).filter(Boolean)}function preview(){const a=parseBatch();$('batchPreview').textContent=`${faNum(a.length)} مورد شناسایی شد${a.length>50?' — بیش از سقف ۵۰ مورد':''}.`}ta.addEventListener('input',preview);$('csvFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{ta.value=await f.text();$('fileName').textContent=f.name;preview()}catch(_){toast('خواندن فایل انجام نشد.')}};
function tableRows(rows,target){$(target).replaceChildren(...rows.map(r=>{let tr=document.createElement('tr');[r.card,r.bank,r.name||'—',r.ok?'موفق':'ناموفق',sourceText(r.source)].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});return tr}))}
$('batchBtn').onclick=async()=>{let cards=parseBatch();if(!cards.length){toast('ابتدا کارت‌ها را وارد کنید.');return}if(cards.length>50){toast('حداکثر ۵۰ مورد مجاز است.');return}const b=$('batchBtn');setbusy(b,true,'اجرای دسته');$('progressBar').style.width='15%';try{let j=await post('batch',{cards:ta.value});batchResults=j.results||[];tableRows(batchResults,'batchRows');$('progressBar').style.width='100%';$('batchCsv').disabled=!batchResults.length;$('batchJson').disabled=!batchResults.length;batchResults.forEach(addHistory);toast(j.message||'پردازش انجام شد.')}catch(err){toast(err.message);$('progressBar').style.width='0%'}finally{setbusy(b,false,'اجرای دسته')}};
function download(filename,text,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function csv(rows){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return '\ufeff'+[['شماره ماسک‌شده','چهار رقم پایانی','بانک','نام','وضعیت','منبع','زمان'],...rows.map(r=>[r.card,r.last4,r.bank,r.name,r.ok?'موفق':'ناموفق',sourceText(r.source),r.time])].map(r=>r.map(q).join(',')).join('\r\n')}
$('batchCsv').onclick=()=>download('zohal-batch.csv',csv(batchResults),'text/csv;charset=utf-8');$('batchJson').onclick=()=>download('zohal-batch.json',JSON.stringify(batchResults,null,2),'application/json;charset=utf-8');
function renderHistory(){let a=history(),term=$('historySearch').value.trim().toLowerCase();let filtered=a.filter(r=>[r.name,r.bank,r.last4,r.card].join(' ').toLowerCase().includes(term));$('stats').textContent=`کل ${faNum(a.length)} · موفق ${faNum(a.filter(x=>x.ok).length)} · نمایشی ${faNum(a.filter(x=>x.source==='demo').length)}`;let body=$('historyRows');body.replaceChildren(...filtered.map(r=>{let tr=document.createElement('tr');[new Date(r.time).toLocaleString('fa-IR'),r.card,r.bank,r.name||'—',sourceText(r.source)].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});let td=document.createElement('td'),b=document.createElement('button');b.className='btn smallbtn';b.textContent='حذف';b.onclick=()=>{saveHistory(history().filter(x=>x.id!==r.id));renderHistory()};td.append(b);tr.append(td);return tr}))}
$('historySearch').oninput=renderHistory;$('clearHistory').onclick=()=>{if(confirm('تمام تاریخچهٔ محلی پاک شود؟')){localStorage.removeItem(storage);renderHistory()}};$('historyJson').onclick=()=>download('zohal-history.json',JSON.stringify(history(),null,2),'application/json;charset=utf-8');$('historyCsv').onclick=()=>download('zohal-history.csv',csv(history()),'text/csv;charset=utf-8');
})();
</script></body></html>
